def parse():
    out = []
    for ln in RAW.strip().split('\n'):
        sec, key, label, dress, props, setting, act, extra = ln.split('|')
        L = lambda x: [i.strip() for i in x.split(';') if i.strip()]
        out.append(dict(sec=sec, key=key, label=label, dress=L(dress), props=L(props), setting=L(setting), action=L(act)))
    return out
